lines = []
start_id = 301
for i, (w, p, m, e, ec, f, t) in enumerate(words):
    tags_str = json.dumps(t, ensure_ascii=False)
    lines.append(f'  {{ id: {start_id + i}, word: "{w}", phonetic: "{p}", meaning: "{m}", example: "{e}", exampleCn: "{ec}", frequency: {f}, tags: {tags_str} }},')

with open('vocabulary.js', 'r', encoding='utf-8') as f:
    content = f.read()

content = content.rstrip().rstrip(';').rstrip().rstrip(']')
content = content + '\n\n  // 商务邮件与沟通 (frequency 12)\n' + '\n'.join(lines) + '\n];'

with open('vocabulary.js', 'w', encoding='utf-8') as f:
    f.write(content)

print('done')
